@log_input_and_output
def get_default_admin_connection_alias(bts_id=0, du_id=0, bts_type='GNB', use_proxy=False, second_gnb=False):
    """
    Returns default admin connection alias. Format of alias is the same
    as the one used by taf.rfrl.bts keywords.
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :type bts_id: int
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :type du_id: int
    :param bts_type: Device that user would like to obtain HTTP connection host to, might be 'gnb' or 'enb'
    :type bts_type: str
    :param use_proxy: returns alias 'lte_vm' for connecting to ENB via VM when True and bts_type='ENB',
                      False at default returns 'lte' for ENB
    :type: bool
    :param second_gnb: returns alias 'second_gnb_vm' for connecting to second gNB via VM when True and bts_type='GNB'
                       and use_proxy=False. Defaults to False, should be set True only in case of connection to
                       secondary gNB SMOD.
    :type: bool
    :return: admin connection alias
    :rtype: str
    """
    if use_proxy and bts_type == 'ENB':
        return 'lte_vm'
    elif use_proxy and bts_type == 'GNB':
        return 'slave_gnb_vm'
    elif second_gnb and bts_type == 'GNB':
        return 'second_gnb_vm'
    else:
        return rest_bts_du.format(bts_type, bts_id, du_id)


@log_input_and_output
def get_http_connection_credentials(bts_type='GNB', bts_id=0):
    """
    Returns HTTP connection credentials needed for admin CLI connection.
    :param bts_type: Device that user would like to obtain HTTP connection host to, might be 'gnb' or 'enb'
    :type bts_type: str
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :type bts_id: int
    :return: HTTP connection credentials.
    :rtype: dict(str, str)
    """
    return TestLine().get_http_credentials(bts_type=bts_type, bts_id=bts_id)


@log_input_and_output
def get_ssh_connection_credentials(bts_type='GNB', bts_id=0, common_unit_id=0):
    """
    Returns SSH connection credentials needed for admin CLI connection.
    :param bts_type: Device that user would like to obtain SSH connection host to, might be 'GNB' or 'ENB'
    :type bts_type: str
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
    :type bts_id: int
    :param common_unit_id: ID of Common Unit for which ssh credentials should be returned; default value 0.
    :type common_unit_id: int
    :return: SSH connection credentials, e.g. {'username': 'usr', 'password': 'pwd', 'host': '1.1.1.1'}
    :rtype: dict(str, str)
    """
    return _get_ssh_connection_credentials(bts_type=bts_type, bts_id=bts_id, common_unit_id=common_unit_id)


@log_input_and_output
def wait_for_site(ip, bts_type, slave, timeout, ssh_credentials=None):
    """
    Waits for site with given IP address to become reachable before timeout expires.
    :param ip: site IP address which should be checked.
    :type ip: str
    :param bts_type: type of BTS which should be checked; either 'GNB' or 'ENB'.
    :type bts_type: str
    :param slave: should be True for slave site (i.e. for fullrack configuration), False otherwise;
                  for slave site additional fixed IPs are checked on top of provided IP;
                  when set to True then ssh_credentials cannot be None (as SSH tunneling through slave test PC must be used).
    :type slave: bool
    :param timeout: time (in seconds) to wait for site to become reachable.
    :type timeout: int
    :param ssh_credentials: SSH host address, username and password which are required to be provided if SSH tunnel is needed to reach site;
                            i.e. {'host': '10.44.254.45', 'user': 'ute', 'password': 'ute'}
    :type ssh_credentials: dict(str, str)
    :return: tuple containing two values: (result, ip);
             result is True if site is reachable, False otherwise;
             ip contains reachable IP of site if result is True, None otherwise (especially relevant for slave site as multiple IPs are checked);
             i.e. (True, '192.168.255.7') or (False, None)
    :rtype: tuple(bool, str or None)
    :raises SSHCredentialsError: if slave is True and ssh_credentials is None
    """
    log_msg = f'Checking if {bts_type}{" slave" if slave else ""} BTS is reachable...'
    log_operation(log_msg)
    url = f'https://{ip}'

    if slave:
        slave_credentials = _get_ssh_connection_credentials(bts_type=bts_type, common_unit_id=1)
        slave_urls = [url,
                      f'https://{slave_credentials["host"]}',
                      'https://192.168.255.7',
                      'https://192.168.255.119']

    if not slave and not ssh_credentials:
        is_reachable = _wait_for_desired_site_state(url=url,
                                                    timeout=timeout,
                                                    should_be_reachable=True)
        return is_reachable, ip if is_reachable else None
    elif not slave and ssh_credentials:
        is_reachable = _wait_for_desired_site_state(url=url,
                                                    timeout=timeout,
                                                    should_be_reachable=True,
                                                    ssh_host=ssh_credentials['host'],
                                                    ssh_username=ssh_credentials['user'],
                                                    ssh_password=ssh_credentials['password'])
        return is_reachable, ip if is_reachable else None
    elif slave and ssh_credentials:
        is_reachable, reachable_ip = _wait_for_any_site_state(urls=slave_urls,
                                                              timeout=timeout,
                                                              should_any_be_reachable=True,
                                                              ssh_host=ssh_credentials['host'],
                                                              ssh_username=ssh_credentials['user'],
                                                              ssh_password=ssh_credentials['password'])
        return is_reachable, reachable_ip
    elif slave and not ssh_credentials:
        raise SSHCredentialsError(f'SSH credentials are required to check if {bts_type} slave BTS is reachable.')


@log_input_and_output
def wait_for_desired_site_state(url, timeout, should_be_reachable, interval=1, ssh_host=None, ssh_port=22,
                                ssh_username=None, ssh_password=None, local_host='localhost', local_port=2137):
    """
    Waits until site under given url is in desired state or timeout expires. Desired state is defined by
    should_be_reachable parameter. If SSH tunnel is needed to reach site, user needs to provide SSH server address,
    port, username and password. If SSH tunnel is not needed, user can omit these parameters.
    :param url: site url i.e. https://192.168.255.129
    :type url: str
    :param timeout: time in seconds to wait for site to reach desired state
    :type timeout: Union[int, str]
    :param should_be_reachable: if desired state for site under url is to be reachable
    :type should_be_reachable: bool
    :param interval: time in seconds between checks, default is 1
    :type interval: int
    :param ssh_host: SSH server address.
    :type ssh_host: str
    :param ssh_port: SSH server port. Default is 22.
    :type ssh_port: int
    :param ssh_username: SSH server username.
    :type ssh_username: str
    :param ssh_password: SSH server password.
    :type ssh_password: str
    :param local_host: Local host to forward traffic from. Default is 'localhost'.
    :type local_host: str
    :param local_port: Local port to forward traffic from. Default is 2137.
    :type local_port: int
    :return: True if site is in desired state, False otherwise
    :rtype: bool
    """
    return _wait_for_desired_site_state(url, timeout, should_be_reachable, interval, ssh_host, ssh_port,
                                        ssh_username, ssh_password, local_host, local_port)


@log_input_and_output
def wait_for_any_site_state(urls, timeout, should_any_be_reachable, interval=1, ssh_host=None, ssh_port=22,
                            ssh_username=None, ssh_password=None, local_host='localhost'):
    """
    Waits until one of the sites under given urls is in desired state or timeout expires. Desired state is defined by
    `should_any_be_reachable` parameter. If SSH tunnel are needed to reach sites, user needs to provide SSH
    server address, port, username and password. If SSH tunnel is not needed, user can omit these parameters.
    :param urls: list of sites urls i.e. [https://192.168.255.129, https://192.168.255.7]
    :type urls: list[str]
    :param timeout: time in seconds to wait for site to reach desired state
    :type timeout: Union[int, str]
    :param should_any_be_reachable: if any site under urls should be reachable
    :type should_any_be_reachable: bool
    :param interval: time in seconds between checks, default is 1
    :type interval: int
    :param ssh_host: SSH server address.
    :type ssh_host: str
    :param ssh_port: SSH server port. Default is 22.
    :type ssh_port: int
    :param ssh_username: SSH server username.
    :type ssh_username: str
    :param ssh_password: SSH server password.
    :type ssh_password: str
    :param local_host: Local host to forward traffic from. Default is 'localhost'.
    :type local_host: str
    :return: tuple containing two values: (result, ip);
             result is True if site is in desired state, False otherwise;
             ip contains IP address of site that is in desired state if result is True, None otherwise.
             i.e. (True, '192.168.255.7') or (False, None)
    :rtype: tuple(bool, str or None)
    """
    return _wait_for_any_site_state(urls, timeout, should_any_be_reachable, interval, ssh_host, ssh_port,
                                    ssh_username, ssh_password, local_host)


@log_input_and_output
def get_details_to_login_via_rmod_config(rmod_config):
    """
    Gets details for logging to rmod
    :param rmod_config: rmod object from from taf.config.testline.gnb.du.RU
    :type rmod_config: RU
    :return: dictionary with address, username, password for logging to rmod,
             e.g.: {"address": "1.1.1.1", "username": "name", "password": "password"}
    :rtype: dict
    :raises SwStreamDoseNotExist: if there was no username or password provided for stream currently on bts
    """
    password = rmod_config.default_ssh_connection_details.password
    username = rmod_config.default_ssh_connection_details.username
    if isinstance(password, dict):
        password = _get_password_for_current_stream(rmod_config)

    if isinstance(username, dict):
        username = _get_username_for_current_stream(rmod_config)

    return {"address": rmod_config.default_ssh_connection_details.addr,
            "username": username,
            "password": password}


@log_input_and_output
def open_admin_connection(alias, bts_type='GNB', bts_id=0, logs_path=None, timeout=60):
    """
    Opens admin connection to the BTS. If connection with given alias is already open, it will be reused.
    :param alias: alias for the connection
    :type alias: str
    :param bts_type: type of BTS to connect to; either 'GNB' or 'ENB'; defaults to 'GNB'
    :type bts_type: str
    :param bts_id: BTS (eNB/gNB) id - related to testline configuration; defaults to 0
    :type bts_id: int
    :param logs_path: path to the directory where admin API logs will be stored;
                      defaults to None (default admin logs path will be used)
    :type logs_path: str
    :param timeout: timeout (in seconds) for the connection to be opened; defaults to 60
    :type timeout: int
    """
    admin_credentials = TestLine().get_http_credentials(bts_type=bts_type, bts_id=bts_id)
    admin_api = admin()
    admin_api.connect_to(bts_host=admin_credentials['ip'],
                         bts_port=admin_credentials['port'],
                         username=admin_credentials['username'],
                         password=admin_credentials['password'],
                         name=alias,
                         admin_api_log_dir=logs_path if logs_path else '',
                         timeout=timeout)


def _get_ssh_connection_credentials(bts_type='GNB', bts_id=0, common_unit_id=0):
    return TestLine().get_ssh_credentials(bts_type=bts_type, bts_id=bts_id, common_unit_id=common_unit_id)


def _wait_for_desired_site_state(url, timeout, should_be_reachable, interval=1, ssh_host=None, ssh_port=22,
                                 ssh_username=None, ssh_password=None, local_host='localhost', local_port=2137):
    ssh_tunnel = None
    _timeout = time.time() + int(timeout)

    try:
        if ssh_host and ssh_port and ssh_username and ssh_password:
            protocol = "https" if "https:" in url else "http"
            port = 443 if protocol == "https" else 80
            host = url.split("://")[1]

            ssh_tunnel = establish_ssh_tunnel(ssh_host, ssh_port, ssh_username, ssh_password, host, port,
                                              local_host, local_port)
            url = f"{protocol}://{ssh_tunnel.local_host}:{ssh_tunnel.local_port}"

        while time.time() <= _timeout:
            is_reachable = _is_url_reachable(url)
            if (is_reachable and should_be_reachable) or (not is_reachable and not should_be_reachable):
                reachability = 'reachable' if should_be_reachable else 'unreachable'
                log_env_state('Site is {} as expected'.format(reachability))
                return True
            time.sleep(interval)
        return False
    finally:
        if ssh_tunnel:
            ssh_tunnel.close()


def _wait_for_any_site_state(urls, timeout, should_any_be_reachable, interval=1, ssh_host=None, ssh_port=22,
                             ssh_username=None, ssh_password=None, local_host='localhost'):
    ssh_tunnels = []
    urls_to_check = []
    local_port = 9000
    _timeout = time.time() + int(timeout)

    try:
        if ssh_host and ssh_port and ssh_username and ssh_password:
            for url in urls:
                protocol = "https" if "https:" in url else "http"
                port = 443 if protocol == "https" else 80
                host = url.split("://")[1]

                ssh_tunnel = establish_ssh_tunnel(ssh_host, ssh_port, ssh_username, ssh_password, host, port,
                                                  local_host, local_port)
                url = f"{protocol}://{ssh_tunnel.local_host}:{ssh_tunnel.local_port}"

                ssh_tunnels.append(ssh_tunnel)
                url_to_check = (url, host)
                urls_to_check.append(url_to_check)
                local_port += 1
        else:
            urls_to_check = [(url, url.split("://")[1]) for url in urls]

        while time.time() <= _timeout:
            for url, ip in urls_to_check:
                is_reachable = _is_url_reachable(url)
                if (is_reachable and should_any_be_reachable) or (not is_reachable and not should_any_be_reachable):
                    reachability = 'reachable' if should_any_be_reachable else 'unreachable'
                    log_env_state('Site is {} via HTTP as expected'.format(reachability))
                    return True, ip
            time.sleep(interval)
        return False, None
    finally:
        if ssh_tunnels:
            for ssh_tunnel in ssh_tunnels:
                ssh_tunnel.close()


def _get_password_for_current_stream(rmod_obj):
    stream = get_sw_stream(device=TestLine().get_type_of_setup())
    try:
        password = rmod_obj.default_ssh_connection_details.password[stream]
    except KeyError:
        raise SwStreamDoseNotExist("There is no password for rmod with serial number: {} for stream: {} in init "
                                   "file.".format(rmod_obj.serial_number, stream))

    return password


def _get_username_for_current_stream(rmod_obj):
    stream = get_sw_stream(device=TestLine().get_type_of_setup())
    try:
        username = rmod_obj.default_ssh_connection_details.username[stream]
    except KeyError:
        raise SwStreamDoseNotExist("There is no username for rmod with serial number: {} for stream: {} in init "
                                   "file.".format(rmod_obj.serial_number, stream))

    return username


@log_input_and_output
def _is_url_reachable(url, timeout=5):
    try:
        response = requests.get(url, verify=False, timeout=timeout)
        return response.ok
    except requests.exceptions.ConnectionError:
        return False
    except requests.exceptions.ReadTimeout:
        return False
